// STEP 2A - PARSE & VALIDATE
// Extract the suspicious IP from the Wazuh alert payload

const payload = $input.first().json.body;

// Extract fields from Wazuh alert structure
const alertData = {
  suspiciousIP:   payload?.data?.srcip || payload?.srcip || 'MISSING_IP',
  agentName:      payload?.agent?.name || 'unknown-agent',
  ruleid:         payload?.rule?.id || '0',
  ruleDescription:payload?.rule?.description || 'No description',
  alertLevel:     payload?.rule?.level || 0,
  timestamp:      payload?.timestamp || new Date().toISOString()
};

// Basic IP format validation
const ipRegex = /^(\d{1,3}\.){3}\d{1,3}$/;
if (!ipRegex.test(alertData.suspiciousIP)) {
  throw new Error(`Invalid IP format: ${alertData.suspiciousIP}`);
}

return [{ json: alertData }];

// STEP 2C - MERGE CTI DATA WITH ORIGINAL ALERT
// Merge AbuseIPDB response back with the original alert context

const ctiData = $input.first().json.data;
const originalAlert = $('02 - Parse & Extract IP').first().json;

return [{
  json: {
    // Original alert context
    suspiciousIP:      originalAlert.suspiciousIP,
    agentName:         originalAlert.agentName,
    ruleId:            originalAlert.ruleid,
    ruleDescription:   originalAlert.ruleDescription,
    alertLevel:        originalAlert.alertLevel,
    alertTimestamp:    originalAlert.timestamp,

    // CTI Enrichment from AbuseIPDB
    abuseScore:        ctiData.abuseConfidenceScore,
    totalReports:      ctiData.totalReports,
    countryCode:       ctiData.countryCode,
    usageType:         ctiData.usageType,
    isp:               ctiData.isp,
    domain:            ctiData.domain,
    isPublic:          ctiData.isPublic,
    isWhitelisted:     ctiData.isWhitelisted,

    // Derived risk classification
    riskLevel: ctiData.abuseConfidenceScore >= 80 ? 'CRITICAL' :
               ctiData.abuseConfidenceScore >= 50 ? 'HIGH' :
               ctiData.abuseConfidenceScore >= 20 ? 'MEDIUM' : 'LOW'
  }
}];

// STEP 3B - PARSE CLOUD CONTEXT RESPONSE
// Normalize the AWS response and prepare the final enriched payload

const ctiEnriched = $('04 - Merge CTI + Alert Data').first().json;

// NOTE: AWS API returns XML. In a real implementation,
// use the AWS n8n node or parse XML with a Set node.
// This code assumes a pre-parsed JSON response for the skeleton.
const awsResponse = $input.first().json;

// Check if any network interfaces were found (IP touched AWS assets)
const networkInterfaces = awsResponse?.DescribeNetworkInterfacesResponse
  ?.networkInterfaceSet?.item || [];

const affectedAssets = Array.isArray(networkInterfaces)
  ? networkInterfaces.map(ni => ({
      interfaceId:  ni.networkInterfaceId,
      instanceId:   ni.attachment?.instanceId || 'N/A',
      vpcId:        ni.vpcId,
      subnetId:     ni.subnetId,
      privateIp:    ni.privateIpAddress,
      status:       ni.status
    }))
  : [];

return [{
  json: {
    ...ctiEnriched,
    cloudProvider:    'AWS',
    cloudTouched:     affectedAssets.length > 0,
    affectedAssets:   affectedAssets,
    assetCount:       affectedAssets.length,
    escalationNeeded: affectedAssets.length > 0
  }
}];

// STEP 4A - BUILD SLACK MESSAGE (HIGH RISK)
// Construct a rich, actionable Slack Block Kit message

const d = $input.first().json;

const assetList = d.affectedAssets && d.affectedAssets.length > 0
  ? d.affectedAssets.map(a => `• Instance: *${a.instanceId}* | VPC: ${a.vpcId} | Status: ${a.status}`).join('\n')
  : '• No cloud assets directly affected.';

const message = {
  channel: '#soc-alerts',
  username: 'CTI-Bot | n8n SOAR',
  icon_emoji: ':shield:',
  blocks: [
    {
      type: 'header',
      text: {
        type: 'plain_text',
        text: `🚨 CRITICAL THREAT DETECTED — Score: ${d.abuseScore}/100`,
        emoji: true
      }
    },
    {
      type: 'section',
      fields: [
        { type: 'mrkdwn', text: `*Suspicious IP:*\n\`${d.suspiciousIP}\`` },
        { type: 'mrkdwn', text: `*Risk Level:*\n${d.riskLevel}` },
        { type: 'mrkdwn', text: `*Abuse Score:*\n${d.abuseScore}/100` },
        { type: 'mrkdwn', text: `*Total Reports:*\n${d.totalReports}` },
        { type: 'mrkdwn', text: `*Country:*\n${d.countryCode}` },
        { type: 'mrkdwn', text: `*ISP/Domain:*\n${d.isp} / ${d.domain}` },
        { type: 'mrkdwn', text: `*Usage Type:*\n${d.usageType}` },
        { type: 'mrkdwn', text: `*Cloud Assets Touched:*\n${d.cloudTouched ? '⚠️ YES' : '✅ No'}` }
      ]
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*Wazuh Rule:* [${d.ruleId}] ${d.ruleDescription}\n*Agent:* ${d.agentName}\n*Detected at:* ${d.alertTimestamp}`
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*Affected Cloud Assets (${d.assetCount}):*\n${assetList}`
      }
    },
    {
      type: 'actions',
      elements: [
        {
          type: 'button',
          text: { type: 'plain_text', text: '🔴 Block IP on Firewall', emoji: true },
          style: 'danger',
          url: `https://YOUR-FIREWALL-CONSOLE/block?ip=${d.suspiciousIP}`,
          action_id: 'block_ip'
        },
        {
          type: 'button',
          text: { type: 'plain_text', text: '🔍 View on AbuseIPDB', emoji: true },
          url: `https://www.abuseipdb.com/check/${d.suspiciousIP}`,
          action_id: 'view_abuseipdb'
        },
        {
          type: 'button',
          text: { type: 'plain_text', text: '📋 Open Ticket in JIRA', emoji: true },
          url: `https://YOUR-JIRA/create?summary=Malicious+IP+${d.suspiciousIP}`,
          action_id: 'open_ticket'
        }
      ]
    },
    {
      type: 'context',
      elements: [{
        type: 'mrkdwn',
        text: `_Automated by CTI-Enrichment-n8n SOAR Pipeline | ${new Date().toISOString()}_`
      }]
    }
  ]
};

return [{ json: message }];

// STEP 4C - LOG LOW RISK ALERT
// For low-risk IPs, just log to a less critical channel

const d = $input.first().json;

return [{
  json: {
    channel: '#soc-logs',
    text: `ℹ️ *LOW RISK IP Detected* | IP: \`${d.suspiciousIP}\` | Score: ${d.abuseScore}/100 | ISP: ${d.isp} | Country: ${d.countryCode} | Agent: ${d.agentName} | Rule: [${d.ruleId}] | _No action required. Logged for audit._`
  }
}];
